{
  "claims": [
    {
      "claim": "A cabin is a small room or apartment.",
      "britannica_quote": "a fmall room, or apartment",
      "verdict": "agrees",
      "wikipedia_quote": "A cabin or berthing is an enclosed space generally on a ship or an aircraft.",
      "passage": 1,
      "note": "Both define a cabin as a small enclosed space on a ship."
    },
    {
      "claim": "Cabins are for officers to lie in.",
      "britannica_quote": "for the officers of the flip to lie in.",
      "verdict": "agrees",
      "wikipedia_quote": "Officers normally have their own cabins—sometimes referred to as staterooms",
      "passage": 2,
      "note": "Wikipedia confirms officers have their own cabins, consistent with sleeping quarters."
    },
    {
      "claim": "The great cabin is the chief of all cabins.",
      "britannica_quote": "The great cabin is the chief of all",
      "verdict": "agrees",
      "wikipedia_quote": "The captain or commanding officer would occupy the \"great cabin\" that normally spanned the width of the stern and had large windows.",
      "passage": 1,
      "note": "Wikipedia assigns the great cabin to the captain, indicating it is the principal cabin."
    },
    {
      "claim": "The great cabin belongs to the captain or chief commander.",
      "britannica_quote": "and that which properly belongs to the captain or chief commander.",
      "verdict": "agrees",
      "wikipedia_quote": "On a warship, it was a privileged area, separate from the rest of the ship, for the exclusive use of the captain.",
      "passage": 1,
      "note": "Wikipedia confirms the great cabin is for the exclusive use of the captain."
    }
  ]
}
